const { useEffect, useId, useRef, useState } = React;

const DURATION_MS = 600;
const WINDOW_MS = 900;
const BEHAVIORS = ["normal", "allow-discrete"];
const toPercent = time => (Math.min(time, WINDOW_MS) / WINDOW_MS) * 100;

// 把逐帧采样里某个布尔量为真的连续区间合并成条带
const toRuns = (samples, key) => {
  const runs = [];
  let start = null;
  samples.forEach((sample, index) => {
    if (sample[key] && start === null) start = sample.t;
    const ended = !sample[key] || index === samples.length - 1;
    if (ended && start !== null) {
      runs.push([start, sample.t]);
      start = null;
    }
  });
  return runs;
};

const Track = ({ label, children }) => (
  <div className="flex items-center gap-2">
    <span className="w-14 shrink-0 font-tau-mono text-tau-tiny text-ink-3">{label}</span>
    <div className="relative min-w-0 flex-1">
      {children}
      <span className="absolute inset-y-0 w-px border-l border-dashed border-line-1" style={{ left: `${toPercent(DURATION_MS)}%` }} />
    </div>
  </div>
);

const Timeline = ({ samples }) => {
  const line = samples.map(sample => `${toPercent(sample.t)},${100 - sample.opacity * 100}`).join(" ");
  return (
    <div className="flex flex-col gap-2">
      <Track label="opacity">
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="block h-12 w-full overflow-visible border-b border-line-1">
          {line && <polyline points={line} className="fill-none stroke-accent" strokeWidth="2" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />}
        </svg>
      </Track>
      <Track label="display">
        <div className="relative h-2.5 rounded-full bg-hover">
          {toRuns(samples, "shown").map(([from, to]) => (
            <span key={from} className="absolute inset-y-0 rounded-full bg-ok" style={{ left: `${toPercent(from)}%`, width: `${Math.max(toPercent(to) - toPercent(from), 1)}%` }} />
          ))}
        </div>
      </Track>
      <div className="flex justify-between pl-16 font-tau-mono text-tau-tiny text-ink-3">
        <span>0s</span>
        <span>过渡结束 0.6s</span>
      </div>
    </div>
  );
};

const Mark = ({ children }) => <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{children}</span>;

const Component = () => {
  const anchor = `--cb-tb-${useId().replace(/[^\w-]/g, "")}`;
  const buttonRef = useRef(null);
  const popoverRef = useRef(null);
  const frameRef = useRef(0);
  const [behavior, setBehavior] = useState("allow-discrete");
  const [starting, setStarting] = useState(true);
  const [direction, setDirection] = useState(null);
  const [samples, setSamples] = useState([]);

  useEffect(() => {
    const button = buttonRef.current;
    const popover = popoverRef.current;
    if ("popoverTargetElement" in button) button.popoverTargetElement = popover;
    // 打开或关闭的瞬间开始逐帧读取计算样式，记录 display 何时切换
    const onBeforeToggle = event => {
      cancelAnimationFrame(frameRef.current);
      setDirection(event.newState === "open" ? "打开" : "关闭");
      const points = [];
      let start = 0;
      const tick = now => {
        start ||= now;
        const style = getComputedStyle(popover);
        points.push({ t: now - start, opacity: Number(style.opacity) || 0, shown: style.display !== "none" });
        setSamples([...points]);
        if (now - start < WINDOW_MS) frameRef.current = requestAnimationFrame(tick);
      };
      frameRef.current = requestAnimationFrame(tick);
    };
    popover.addEventListener("beforetoggle", onBeforeToggle);
    return () => {
      popover.removeEventListener("beforetoggle", onBeforeToggle);
      cancelAnimationFrame(frameRef.current);
      if (popover.matches?.(":popover-open")) popover.hidePopover();
    };
  }, []);

  const opening = direction === "打开";
  const switchAt = direction ? samples.find(sample => sample.shown === opening)?.t : undefined;
  const last = samples[samples.length - 1];

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-tb-anchor { anchor-name: ${anchor}; }
          .cb-tb-pop {
            position-anchor: ${anchor};
            inset: auto;
            top: anchor(bottom);
            left: anchor(center);
            translate: -50% 8px;
            margin: 0;
            opacity: 0;
            scale: 0.95;
            transition: opacity ${DURATION_MS}ms, scale ${DURATION_MS}ms, display ${DURATION_MS}ms ${behavior};
          }
          .cb-tb-pop:popover-open { opacity: 1; scale: 1; }
          ${starting ? "@starting-style { .cb-tb-pop:popover-open { opacity: 0; scale: 0.95; } }" : ""}
        }
      `}</style>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div className="flex min-h-[180px] min-w-0 items-start justify-center rounded-tau-md border border-line-1 p-4 pt-10">
          <button
            ref={buttonRef}
            type="button"
            className="cb-tb-anchor cursor-pointer rounded-tau-sm bg-accent px-3 py-1.5 text-tau-body text-ink-inverse shadow-card hover:opacity-90"
          >
            切换 Popover
          </button>
          <div ref={popoverRef} popover="auto" className="cb-tb-pop rounded-tau-md border border-line-1 bg-surface px-3 py-2 text-tau-body text-ink-1 shadow-lift">
            Hello from popover!
          </div>
        </div>
        <div className="flex flex-col gap-3 rounded-tau-md border border-line-1 p-3">
          <div className="flex items-baseline justify-between gap-2">
            <span className="text-tau-sm text-ink-3">{direction ? `最近一次：${direction}` : "计算样式采样"}</span>
            {last && (
              <span className="font-tau-mono text-tau-sm text-ink-2">
                {last.shown ? "block" : "none"} / {last.opacity.toFixed(2)}
              </span>
            )}
          </div>
          <Timeline samples={samples} />
          <p className="m-0 text-tau-meta text-ink-2">
            {switchAt === undefined
              ? "点击左侧按钮打开或关闭，记录 display 与 opacity 的变化"
              : `display 在约 ${Math.round(switchAt / 10) * 10}ms 变为 ${opening ? "block" : "none"}`}
          </p>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-x-6 gap-y-3">
        <ui.RadioGroup label="display 的 transition-behavior" value={behavior} onValueChange={setBehavior} orientation="horizontal">
          {BEHAVIORS.map(value => (
            <ui.Radio key={value} value={value} label={value} />
          ))}
        </ui.RadioGroup>
        <ui.Switch size="sm" checked={starting} onCheckedChange={setStarting} label="@starting-style 首帧" />
      </div>
      <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
        <div>{"[popover] {"}</div>
        <div>{"  opacity: 0;"}</div>
        <div>
          {"  transition: opacity 0.6s, display 0.6s "}
          <Mark>{behavior}</Mark>
          {";"}
        </div>
        <div>{"}"}</div>
        <div>{"[popover]:popover-open { opacity: 1; }"}</div>
        {starting ? (
          <div>
            <Mark>@starting-style</Mark>
            {" { [popover]:popover-open { opacity: 0; } }"}
          </div>
        ) : (
          <div className="text-ink-3">{"/* 未设置 @starting-style：打开时没有起始帧 */"}</div>
        )}
      </pre>
    </div>
  );
};

