const { useEffect, useId, useRef, useState } = React;

const DURATION_MS = 800;
const WINDOW_MS = 1100;
const toPercent = time => (Math.min(time, WINDOW_MS) / WINDOW_MS) * 100;

// 把逐帧采样里某个布尔量为真的连续区间合并成条带
const toRuns = (samples, key) => {
  const runs = [];
  let start = null;
  samples.forEach((sample, index) => {
    if (sample[key] && start === null) start = sample.t;
    const ended = !sample[key] || index === samples.length - 1;
    if (ended && start !== null) {
      runs.push([start, sample.t]);
      start = null;
    }
  });
  return runs;
};

const Track = ({ label, children }) => (
  <div className="flex items-center gap-2">
    <span className="w-14 shrink-0 font-tau-mono text-tau-tiny text-ink-3">{label}</span>
    <div className="relative min-w-0 flex-1">
      {children}
      <span className="absolute inset-y-0 w-px border-l border-dashed border-line-1" style={{ left: `${toPercent(DURATION_MS)}%` }} />
    </div>
  </div>
);

const Bar = ({ samples, field, className }) => (
  <div className="relative h-2.5 rounded-full bg-hover">
    {toRuns(samples, field).map(([from, to]) => (
      <span
        key={from}
        className={`absolute inset-y-0 rounded-full ${className}`}
        style={{ left: `${toPercent(from)}%`, width: `${Math.max(toPercent(to) - toPercent(from), 1)}%` }}
      />
    ))}
  </div>
);

const Timeline = ({ samples }) => {
  const line = samples.map(sample => `${toPercent(sample.t)},${100 - sample.opacity * 100}`).join(" ");
  return (
    <div className="flex flex-col gap-2">
      <Track label="opacity">
        <svg viewBox="0 0 100 100" preserveAspectRatio="none" className="block h-12 w-full overflow-visible border-b border-line-1">
          {line && <polyline points={line} className="fill-none stroke-accent" strokeWidth="2" strokeLinejoin="round" vectorEffect="non-scaling-stroke" />}
        </svg>
      </Track>
      <Track label="display">
        <Bar samples={samples} field="shown" className="bg-ok" />
      </Track>
      <Track label="overlay">
        <Bar samples={samples} field="onTop" className="bg-tag-2" />
      </Track>
      <div className="flex justify-between pl-16 font-tau-mono text-tau-tiny text-ink-3">
        <span>关闭</span>
        <span>过渡结束 0.8s</span>
      </div>
    </div>
  );
};

const Mark = ({ children }) => <span className="rounded-tau-sm bg-accent-soft px-0.5 text-accent-text">{children}</span>;

const Component = () => {
  const anchor = `--cb-ov-${useId().replace(/[^\w-]/g, "")}`;
  const dialogRef = useRef(null);
  const triggerRef = useRef(null);
  const popoverRef = useRef(null);
  const frameRef = useRef(0);
  const [overlay, setOverlay] = useState(true);
  const [samples, setSamples] = useState([]);

  useEffect(() => {
    const dialog = dialogRef.current;
    const trigger = triggerRef.current;
    const popover = popoverRef.current;
    if ("popoverTargetElement" in trigger) trigger.popoverTargetElement = popover;
    // 关闭的瞬间开始逐帧读取计算样式：overlay 为 auto 表示仍留在 top-layer
    const onBeforeToggle = event => {
      cancelAnimationFrame(frameRef.current);
      if (event.newState !== "closed") return setSamples([]);
      const points = [];
      let start = 0;
      const tick = now => {
        start ||= now;
        const style = getComputedStyle(popover);
        points.push({ t: now - start, opacity: Number(style.opacity) || 0, shown: style.display !== "none", onTop: style.overlay === "auto" });
        setSamples([...points]);
        if (now - start < WINDOW_MS) frameRef.current = requestAnimationFrame(tick);
      };
      frameRef.current = requestAnimationFrame(tick);
    };
    const onDialogClose = () => {
      if (popover.matches?.(":popover-open")) popover.hidePopover();
    };
    popover.addEventListener("beforetoggle", onBeforeToggle);
    dialog.addEventListener("close", onDialogClose);
    return () => {
      popover.removeEventListener("beforetoggle", onBeforeToggle);
      dialog.removeEventListener("close", onDialogClose);
      cancelAnimationFrame(frameRef.current);
      if (popover.matches?.(":popover-open")) popover.hidePopover();
      if (dialog.open) dialog.close();
    };
  }, []);

  const transition = [
    `opacity ${DURATION_MS}ms`,
    `translate ${DURATION_MS}ms`,
    `display ${DURATION_MS}ms allow-discrete`,
    overlay ? `overlay ${DURATION_MS}ms allow-discrete` : "",
  ].filter(Boolean).join(", ");
  const onTopFor = samples.filter(sample => sample.onTop).at(-1)?.t;
  const overlaySwitch = <ui.Switch size="sm" checked={overlay} onCheckedChange={setOverlay} label="overlay allow-discrete" />;

  return (
    <div className="flex flex-col gap-3">
      <style>{`
        @scope {
          .cb-ov-anchor { anchor-name: ${anchor}; }
          .cb-ov-dialog::backdrop { background: var(--tau-overlay); }
          .cb-ov-pop {
            position-anchor: ${anchor};
            inset: auto;
            bottom: anchor(top);
            left: anchor(center);
            margin: 0;
            opacity: 0;
            translate: -50% 0;
            transition: ${transition};
          }
          .cb-ov-pop:popover-open { opacity: 1; translate: -50% -8px; }
          @starting-style {
            .cb-ov-pop:popover-open { opacity: 0; translate: -50% 0; }
          }
        }
      `}</style>
      <div className="flex flex-wrap items-center gap-3 rounded-tau-md border border-line-1 p-4">
        <ui.Button variant="primary" size="sm" icon={icons.AppWindow} onClick={() => dialogRef.current?.showModal?.()}>
          打开 Dialog
        </ui.Button>
        {overlaySwitch}
        <span className="ml-auto text-tau-meta text-ink-3">
          {onTopFor === undefined ? "在 Dialog 里打开再关闭 Popover" : `上次关闭：留在 top-layer 约 ${Math.round(onTopFor / 10) * 10}ms`}
        </span>
      </div>
      <pre className="m-0 overflow-x-auto rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
        <div>{"[popover] {"}</div>
        <div>{"  transition:"}</div>
        <div>{"    opacity 0.8s,"}</div>
        <div>{"    translate 0.8s,"}</div>
        <div>{`    display 0.8s allow-discrete${overlay ? "," : ";"}`}</div>
        {overlay ? (
          <div>
            {"    "}
            <Mark>overlay 0.8s allow-discrete</Mark>
            {";"}
          </div>
        ) : (
          <div className="text-ink-3">{"    /* 未设置 overlay */"}</div>
        )}
        <div>{"}"}</div>
      </pre>
      <dialog ref={dialogRef} className="cb-ov-dialog m-auto w-[min(440px,calc(100vw-32px))] rounded-tau-md border border-line-1 bg-surface p-5 text-ink-1 shadow-lift">
        <div className="flex flex-col gap-4">
          <div className="flex items-center justify-between gap-3">
            <span className="text-tau-body text-ink-1">modal dialog（top-layer）</span>
            <ui.IconButton aria-label="关闭 Dialog" onClick={() => dialogRef.current?.close()}>
              <icons.X className="size-4" />
            </ui.IconButton>
          </div>
          <div className="flex justify-center pt-10">
            <button
              ref={triggerRef}
              type="button"
              className="cb-ov-anchor cursor-pointer rounded-tau-sm border border-line-1 bg-surface px-3 py-1.5 text-tau-body text-ink-1 hover:bg-hover"
            >
              切换 Popover
            </button>
          </div>
          {overlaySwitch}
          <div className="rounded-tau-md border border-line-1 p-3">
            <Timeline samples={samples} />
          </div>
        </div>
      </dialog>
      <div ref={popoverRef} popover="auto" className="cb-ov-pop rounded-tau-md bg-accent px-3 py-2 text-tau-body text-ink-inverse shadow-lift">
        关闭时观察退出动画
      </div>
    </div>
  );
};
